/* FilmLook photographer-style similarity engine v1 (ES2017, no dependencies).
 * Mirrors src/filmlook_ml/style/engine.py + profiles.py. Model data (profiles, rarity tables, thresholds,
 * texts, optional learned model) comes from model-data.js, generated by scripts/style_export_js.py.
 */
'use strict';

function sig(z) { return 1 / (1 + Math.exp(-z)); }

function rnd(x, n) { var m = Math.pow(10, n); return Math.floor(x * m + 0.5) / m; }

function dimsFromFeatures(f, M) {
  var x = {}, k;
  for (k in f) if (Object.prototype.hasOwnProperty.call(f, k)) x[k] = f[k];
  x.hue_ry = f.hue_red + f.hue_yellow;
  var out = { monochrome: Math.max(f.mono, sig((0.12 - f.sat_p95) / 0.02)) };
  var names = Object.keys(M.dims);
  for (var i = 0; i < names.length; i++) {
    var d = M.dims[names[i]]; // [feature, center, scale, sign]
    out[names[i]] = sig(d[3] * (x[d[0]] - d[1]) / d[2]);
  }
  return out;
}

function dimProgress(d, t) {
  if (Math.abs(t - 0.5) < 0.1) return Math.max(-1, Math.min(1, 1 - Math.abs(d - t) / 0.25));
  var p = (d - 0.5) / (t - 0.5);
  if (p > 1) p = 2 - p;
  return Math.max(-1, Math.min(1, p));
}

function profileEvidence(dims, prof) {
  var compat = prof.monochrome ? 1 - Math.abs(dims.monochrome - prof.monochrome[0]) : 1;
  var num = 0, den = 0, support = {};
  var keys = Object.keys(prof);
  for (var i = 0; i < keys.length; i++) {
    var k = keys[i];
    if (k === 'monochrome') continue;
    var t = prof[k][0], w = prof[k][1];
    var pr = dimProgress(dims[k], t);
    num += w * pr; den += w; support[k] = pr;
  }
  var ev = den > 0 ? num / den : 0;
  return { score: compat * Math.max(ev, 0), evidence: ev, compat: compat, support: support };
}

function percentile(score, q) {
  var n = q.length - 1;
  if (score <= q[0]) return 0;
  if (score >= q[n]) return 1;
  var lo = 0, hi = n;
  while (hi - lo > 1) {
    var mid = Math.floor((lo + hi) / 2);
    if (q[mid] <= score) lo = mid; else hi = mid;
  }
  var span = q[hi] - q[lo];
  var frac = span > 0 ? (score - q[lo]) / span : 0;
  return (lo + frac) / n;
}

/* ---------------- optional learned models (same feature vector as Python) ---------------- */
function standardize(v, L) {
  var z = new Float64Array(v.length);
  for (var i = 0; i < v.length; i++) z[i] = (v[i] - L.mean[i]) / L.scale[i];
  return z;
}
function softmax(a) {
  var m = -Infinity, i, s = 0, out = new Array(a.length);
  for (i = 0; i < a.length; i++) if (a[i] > m) m = a[i];
  for (i = 0; i < a.length; i++) { out[i] = Math.exp(a[i] - m); s += out[i]; }
  for (i = 0; i < a.length; i++) out[i] /= s;
  return out;
}
function predictLearned(v, L) {
  var z = standardize(v, L), c, i, j, logits;
  if (L.type === 'linear') {
    logits = [];
    for (c = 0; c < L.coef.length; c++) {
      var s = L.intercept[c];
      for (i = 0; i < z.length; i++) s += L.coef[c][i] * z[i];
      logits.push(s);
    }
    return softmax(logits);
  }
  if (L.type === 'forest') {
    var acc = new Array(L.classes.length).fill(0);
    for (var t = 0; t < L.trees.length; t++) {
      var T = L.trees[t], node = 0;
      // sklearn compares float32-cast inputs with its thresholds
      while (T.left[node] !== -1) node = Math.fround(z[T.feature[node]]) <= T.threshold[node] ? T.left[node] : T.right[node];
      for (c = 0; c < acc.length; c++) acc[c] += T.value[node][c];
    }
    for (c = 0; c < acc.length; c++) acc[c] /= L.trees.length;
    return acc;
  }
  if (L.type === 'mlp') {
    var h = z;
    for (var l = 0; l < L.weights.length; l++) {
      var W = L.weights[l], b = L.biases[l], nh = new Array(b.length);
      for (j = 0; j < b.length; j++) {
        var s2 = b[j];
        for (i = 0; i < h.length; i++) s2 += h[i] * W[i][j];
        nh[j] = l < L.weights.length - 1 ? Math.max(0, s2) : s2;
      }
      h = nh;
    }
    return softmax(h);
  }
  throw new Error('unknown learned model type');
}

/* ---------------- main entry: features -> result JSON ---------------- */
function phrase(M, dim, target, lang) { var p = M.phrases[dim][lang]; return target >= 0.5 ? p[0] : p[1]; }

function explain(M, res, prof, mono, lang) {
  var sup = [], con = [], d;
  for (d in res.support) {
    if (!Object.prototype.hasOwnProperty.call(res.support, d)) continue;
    if (mono && M.color_dims.indexOf(d) >= 0) continue;
    var p = res.support[d];
    if (p >= 0.6) sup.push([p, d]);
    if (p < 0) con.push([p, d]);
  }
  sup.sort(function (a, b) { return a[0] !== b[0] ? b[0] - a[0] : (a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0); });
  con.sort(function (a, b) { return a[0] !== b[0] ? a[0] - b[0] : (a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0); });
  var ev = sup.slice(0, 3).map(function (x) { return phrase(M, x[1], prof.profile[x[1]][0], lang); });
  var cn = con.slice(0, 1).map(function (x) { return phrase(M, x[1], prof.profile[x[1]][0], lang); });
  return [ev, cn];
}

function analyzeFeatures(f, M, lang, featureVector) {
  lang = lang || 'en';
  if (lang !== 'en' && lang !== 'zh') throw new Error('unsupported language');
  var dims = dimsFromFeatures(f, M), mono = dims.monochrome >= 0.5, T = M.thresholds;
  var learned = null;
  if (M.learned && featureVector) {
    var pr = predictLearned(featureVector(f), M.learned);
    learned = {};
    for (var c = 0; c < M.learned.classes.length; c++) learned[M.learned.classes[c]] = pr[c];
  }
  var rows = [], ids = Object.keys(M.profiles);
  for (var i = 0; i < ids.length; i++) {
    var pid = ids[i], prof = M.profiles[pid];
    var r = profileEvidence(dims, prof.profile);
    var pct = percentile(r.score, M.quantiles[pid]);
    if (learned && Object.prototype.hasOwnProperty.call(learned, pid)) pct = learned[pid];
    var reliable = r.score >= T.min_score && pct >= T.min_percentile && r.compat >= T.min_compat;
    var strength = reliable && r.score >= T.strong_score && pct >= T.strong_percentile ? 'strong'
      : (reliable ? 'moderate' : 'weak');
    rows.push({ pid: pid, prof: prof, r: r, pct: pct, reliable: reliable, strength: strength,
      key: r.score * (0.5 + 0.5 * pct) });
  }
  rows.sort(function (a, b) { return a.key !== b.key ? b.key - a.key : (a.pid < b.pid ? -1 : a.pid > b.pid ? 1 : 0); });
  var lowInfo = f.y_std < T.min_contrast, matches = [];
  for (i = 0; i < 3; i++) {
    var x = rows[i], ex = explain(M, x.r, x.prof, mono, lang);
    matches.push({ id: x.pid, name: x.prof.name[lang], similarity: rnd(x.r.score, 3), percentile: rnd(x.pct, 3),
      reliable: !!(x.reliable && !lowInfo), strength: M.strength_text[lowInfo ? 'weak' : x.strength][lang],
      evidence: ex[0], counter_evidence: ex[1].map(function (c) { return M.text.differs[lang].replace('{x}', c); }),
      basis: x.prof.basis[lang] });
  }
  var status = matches[0].reliable ? 'match' : 'uncertain';
  var msg = status === 'uncertain' ? (lowInfo ? M.text.low_info[lang] : M.text.uncertain[lang])
    : M.text.match[lang].replace('{name}', matches[0].name);
  var rd = {};
  Object.keys(dims).forEach(function (k) { rd[k] = rnd(dims[k], 4); });
  return { schema_version: M.schema_version, model_version: M.model_version, language: lang, status: status,
    message: msg, monochrome: mono, matches: matches, dims: rd, disclaimer: M.text.disclaimer[lang] };
}

module.exports = { analyzeFeatures: analyzeFeatures, dimsFromFeatures: dimsFromFeatures,
  profileEvidence: profileEvidence, percentile: percentile, predictLearned: predictLearned };
